def hook(specific, msgs):
    return HOOK.replace('__SPECIFIC__', specific or '        pass').replace('__MSGS__', repr(msgs))

def api_node(name, path, body, nxt, specific, msgs, status_var, json_var, transitions, retries=1, timeout=20000, say=None):
    props = {k: {"type": "string", "default": v} for k, v in body.items()}
    return {
        "name": name, "node_type": "api_request", "passthrough": True,
        "passthrough_default_transition": nxt,
        "on_enter": {"type": "tts", "text": say} if say else {"type": "silent"},
        "disable_inactivity_monitor": True,
        "pre_actions": [{
            "type": "function", "config": {"timeoutMs": timeout, "maxRetries": retries},
            "function": {"name": name, "handler": "__function__:api_call", "description": f"POST {path}",
                "parameters": {"type": "object", "properties": {
                    "url": {"type": "string", "default": BASE + path},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": list(body.keys())}}}},
            "post_process_code": hook(specific, msgs)}],
        "response_mapping": [{"path": "data.st", "variable": status_var}, {"path": "data.payload", "variable": json_var}],
        "transitions": transitions + [always(nxt)]}

def code_node(name, code, nxt, transitions):
